private fun PasswordInput(
    password: String,
    isLoggingIn: Boolean,
    isPasswordError: Boolean,
    onPasswordChanged: (String) -> Unit,
    onLoginPressed: () -> Unit
) {
    val keyboardController = LocalSoftwareKeyboardController.current
    var passwordVisible by rememberSaveable { mutableStateOf(false) }
    OutlinedTextField(
        value = password,
        onValueChange = onPasswordChanged,
        leadingIcon = {
            Icon(
                imageVector = Icons.Default.Lock,
                contentDescription = null
            )
        },
        trailingIcon = {
            IconButton(onClick = { passwordVisible = !passwordVisible }) {
                Icon(
                    imageVector = if (passwordVisible) Icons.Default.Visibility else Icons.Default.VisibilityOff,
                    contentDescription = stringResource(
                        id = if (passwordVisible) {
                            StringResource.login_hide_password
                        } else {
                            StringResource.login_show_password
                        }
                    )
                )
            }
        },
        visualTransformation = if (passwordVisible) VisualTransformation.None else PasswordVisualTransformation(),
        keyboardOptions = KeyboardOptions.Default.copy(
            keyboardType = KeyboardType.Password,
            imeAction = ImeAction.Done
        ),
        keyboardActions = KeyboardActions(
            onDone = {
                if (!isLoggingIn) {
                    onLoginPressed()
                    keyboardController?.hide()
                }
            }
        ),
        isError = isPasswordError,
        singleLine = true,
        label = { Text(text = stringResource(id = StringResource.login_password)) },
        modifier = Modifier
            .semantics { testTag = CredentialsTags.Password }
            .autofill(
                autofillTypes = listOf(AutofillType.Password),
                onFill = { onPasswordChanged(it) }
            )
    )
}

